%[text] # Vehicle Speed Reference - Simulation Case
model_name = "HarnessModel_VehSpdRef";
load_system(model_name)

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, gcs + "/Vehicle speed reference", ReferencedSubsystem = "VehSpdRef_FTP75_refsub");
sim_in = setModelParameter(sim_in, StopTime = "2500");
applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

bevutil1.SignalUtil.plotTimedData( ... %[output:group:5b04b4a0] %[output:9509dd69]
  TimedData = sim_data, ... %[output:9509dd69]
  SignalName = "Vehicle speed reference kph", ... %[output:9509dd69]
  FigureHeight = 250, ... %[output:9509dd69]
  FigureWidth = 900 ) %[output:group:5b04b4a0] %[output:9509dd69]
